<?php use ImWiki\Security\Html;$title='Security';?>
<div class="page-head"><div><p class="eyebrow">Administracja</p><h1>Security</h1></div></div><section class="stat-grid"><div class="stat card"><strong><?=Html::e($stats['failed_logins'])?></strong><span>nieudane logowania / 24h</span></div><div class="stat card"><strong><?=Html::e($stats['without_2fa'])?></strong><span>aktywni bez 2FA</span></div><div class="stat card"><strong><?=Html::e($stats['api_tokens'])?></strong><span>aktywne API tokens</span></div><div class="stat card"><strong><?=Html::e($stats['public_shares'])?></strong><span>public shares</span></div><div class="stat card"><strong><?=Html::e($stats['old_sessions'])?></strong><span>sesje starsze niż 30 dni</span></div></section><section class="card section-card"><h2>Ostatnie nieudane logowania</h2><?php if(!$failed):?><div class="empty-state"><p>Brak zdarzeń.</p></div><?php endif;?><?php foreach($failed as $row):?><div class="list-row"><div><strong><?=Html::e($row['login_identifier'])?></strong><small><?=Html::e($row['ip_address'])?> · <?=Html::e($row['created_at'])?><br><?=Html::e(mb_strimwidth($row['user_agent'],0,160,'…'))?></small></div></div><?php endforeach;?></section>
